"""Quality gate for articles generated by the YouTube -> Blog (Gemini) workflow.

This deliberately validates only new content before it enters the video pipeline.
It never rewrites source articles: rejected files are recorded by content hash and
will be reconsidered automatically after an edit.
"""
from __future__ import annotations

import hashlib
import re
from pathlib import Path

import frontmatter


ALLOWED_TAGS = {
    "ai", "ai-agents", "llm", "openai", "google", "anthropic", "nvidia",
    "robotics", "ai-video", "coding", "tech-news", "gadgets", "policy", "research",
}


class BlogPostValidationError(ValueError):
    """Raised when a generated article does not meet the publishing contract."""

    def __init__(self, errors: list[str]):
        self.errors = errors
        super().__init__("; ".join(errors))


def _word_count(text: str) -> int:
    # Remove embeds and HTML attributes before counting visible article words.
    text = re.sub(r"<iframe\b[^>]*>.*?</iframe>", " ", text, flags=re.I | re.S)
    text = re.sub(r'<p class="video-credit">.*?</p>', " ", text, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    return len(re.findall(r"\b[\w]+(?:['’][\w]+)?\b", text, flags=re.UNICODE))


def validate_blog_post(path: str | Path) -> dict:
    """Validate frontmatter and the Gemini article contract; return parsed metadata."""
    path = Path(path)
    errors: list[str] = []
    try:
        raw = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise BlogPostValidationError([f"cannot read UTF-8 article: {exc}"]) from exc

    if not raw.startswith("---"):
        raise BlogPostValidationError(["frontmatter must start with ---"])

    try:
        post = frontmatter.loads(raw)
    except Exception as exc:  # YAML parser errors vary by PyYAML version.
        raise BlogPostValidationError([f"invalid YAML frontmatter: {exc}"]) from exc

    meta = post.metadata
    title = str(meta.get("title") or "").strip()
    description = str(meta.get("description") or "").strip()
    tags = meta.get("tags") or []
    if isinstance(tags, str):
        tags = [item.strip() for item in tags.split(",") if item.strip()]
    if not isinstance(tags, list):
        tags = []

    if not title:
        errors.append("title is required")
    else:
        if len(title) > 120:
            errors.append("title exceeds 120 characters")
        if len(title.split()) > 12:
            errors.append("title exceeds 12 words")

    if not description:
        errors.append("description is required")
    elif len(description) > 160:
        errors.append("description exceeds 160 characters")

    if not isinstance(tags, list) or not 2 <= len(tags) <= 4:
        errors.append("tags must contain 2 to 4 allowed values")
    else:
        unknown = sorted({str(tag).strip().lower() for tag in tags} - ALLOWED_TAGS)
        if unknown:
            errors.append("unsupported tags: " + ", ".join(unknown))

    slug = path.stem.lower()
    slug_words = [part for part in slug.split("-") if part]
    if not 3 <= len(slug_words) <= 8 or not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", slug):
        errors.append("filename slug must contain 3 to 8 lowercase hyphen-separated words")

    body = post.content or ""
    words = _word_count(body)
    if not 600 <= words <= 1200:
        errors.append(f"article body has {words} words; expected 600 to 1200")

    # Exclude the appended source-video embed from the editorial section count.
    article_body = re.sub(
        r"^##\s+Watch the original video\s*$[\s\S]*$",
        "",
        body,
        flags=re.I | re.M,
    )
    h2 = re.findall(r"^##\s+(.+?)\s*$", article_body, flags=re.M)
    if not 3 <= len(h2) <= 5:
        errors.append(f"article must contain 3 to 5 H2 sections (found {len(h2)})")
    if not any(re.search(r"\bwhy it matters\b", heading, flags=re.I) for heading in h2):
        errors.append("article must include a Why it matters section")
    if not re.search(r"\bkey takeaways\b", article_body, flags=re.I):
        errors.append("article must include Key takeaways")
    if re.search(r"^\s*(?:RELEVANT|REASON|TITLE|DESCRIPTION|SLUG|TAGS|IMAGE_QUERY|BODY):", body, flags=re.M):
        errors.append("Gemini response labels leaked into the published article")

    if errors:
        raise BlogPostValidationError(errors)

    return {
        "title": title,
        "description": description,
        "tags": [str(tag).strip().lower() for tag in tags],
        "word_count": words,
        "h2_count": len(h2),
    }



def content_fingerprint(path: str | Path) -> str:
    """SHA-256 of the exact file bytes, used to suppress repeat rejection of unchanged content."""
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def should_retry_rejected_post(path: str | Path, ledger_entry: dict | None) -> bool:
    """Retry a rejected post only after its content changes; new posts always qualify."""
    if not ledger_entry or not ledger_entry.get("quality_rejected_sha"):
        return True
    try:
        return content_fingerprint(path) != ledger_entry["quality_rejected_sha"]
    except OSError:
        return False


def should_process_in_sweep(path: str | Path, ledger_entry: dict | None) -> bool:
    """Select unprocessed posts, or rejected posts whose content has since changed.

    A normal ledger entry means the post has already been processed and must not be
    selected again by the periodic safety sweep. Only a quality-rejection entry can
    become eligible again after its SHA-256 fingerprint changes.
    """
    if ledger_entry is None:
        return True
    if ledger_entry.get("quality_rejected_sha"):
        return should_retry_rejected_post(path, ledger_entry)
    return False
